use verus::*;

#[verifier::spec]
fn hstack(a: Vec<f32>, b: Vec<f32>) -> Vec<f32> {
    // Ensure that the input arrays are not mutated
    requires(!a.is_empty() || !b.is_empty());

    // The length of the resulting array should be the sum of the lengths of the two input arrays
    let n_a = a.len();
    let n_b = b.len();
    let result = Vec::with_capacity(n_a + n_b);

    // Invariant: The result array will contain the elements of a followed by the elements of b
    let mut i = 0;
    while i < n_a {
        result.push(a[i]);
        i += 1;
    }

    let mut j = 0;
    while j < n_b {
        result.push(b[j]);
        j += 1;
    }

    // Ensure the length of the result is correct
    ensures(result.len() == n_a + n_b);

    // Ensure the elements from the first array are in the correct order
    for k in 0..n_a {
        assert(result[k] == a[k]);
    }

    // Ensure the elements from the second array are in the correct order
    for k in 0..n_b {
        assert(result[n_a + k] == b[k]);
    }

    // Return the concatenated result
    result
}